import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        A = next(iterator)
        B = next(iterator)

        adj = [[] for _ in range(20)]
        possible = True

        for i in range(n):
            u = ord(A[i]) - ord('a')
            v = ord(B[i]) - ord('a')

            if u == v:
                continue

            if u > v:
                possible = False
                break

            adj[u].append(v)

        if not possible:
            results.append("-1")
            continue

        moves = 0
        visited = [False] * 20

        for i in range(20):
            if adj[i]:
                adj[i] = list(set(adj[i]))
                if len(adj[i]) > 1:
                    target = min(adj[i])
                    for neighbor in adj[i]:
                        if neighbor != target:
                            adj[target].append(neighbor)
                    adj[i] = [target]

        for i in range(20):
            if adj[i]: 
                if not visited[i]:
                    stack = [i]
                    visited[i] = True
                    while stack:
                        curr = stack.pop()
                        for nxt in adj[curr]:
                            if not visited[nxt]:
                                visited[nxt] = True
                                stack.append(nxt)
                    moves += 1

        results.append(str(moves))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    solve()
